INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10801, 'ក្នុងធរណីមាត្រលំហ សមីការដឺក្រេទី 1 មានបីអញ្ញាត \(ax + by + cz = d\) តាងឱ្យរូបធរណីមាត្រណា?', NULL, '["ប្លង់មួយក្នុងលំហ", "ស្វ៊ែរមួយ", "បន្ទាត់មួយក្នុងលំហ", "ចំណុចមួយ"]', 0, NULL, 1, 'mcq', 'សមីការលីនេអ៊ែរមានបីអញ្ញាត \(ax + by + cz = d\) ក្នុងលំហ \(\mathbb{R}^3\) តាងឱ្យប្លង់មួយ។', 'ប្រព័ន្ធសមីការ', 'easy', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10802, 'រកតម្លៃ \(z\) នៃប្រព័ន្ធ \(\begin{cases} x + y + z = 6 \\ x + y = 4 \\ y + z = 5 \end{cases}\)៖', NULL, '["\\(3\\)", "\\(4\\)", "\\(1\\)", "\\(2\\)"]', 3, NULL, 1, 'mcq', '\(z = (x + y + z) - (x + y) = 6 - 4 = 2\)។', 'ប្រព័ន្ធសមីការ', 'easy', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10803, 'គណនាផលបូក \(x + y + z\) នៃប្រព័ន្ធ \(\begin{cases} x + y = 3 \\ y + z = 5 \\ z + x = 6 \end{cases}\)៖', NULL, '["\\(6\\)", "\\(7\\)", "\\(8\\)", "\\(14\\)"]', 1, NULL, 1, 'mcq', 'បូកសមីការទាំងបីបញ្ចូលគ្នា ៖ \(2(x + y + z) = 3 + 5 + 6 = 14 \implies x + y + z = 7\)។', 'ប្រព័ន្ធសមីការ', 'easy', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10804, 'ពេលដោះស្រាយប្រព័ន្ធសមីការ 3 អញ្ញាតមួយ គេទាញបានសមភាព \(0x + 0y + 0z = 6\)។ តើសំណុំចម្លើយជាអ្វី?', NULL, '["\\(S = \\mathbb{R}\\)", "\\(S = \\{0\\}\\)", "\\(S = \\emptyset \\quad (\\text{គ្មានចម្លើយ})\\)", "\\(S = \\{6\\}\\)"]', 2, NULL, 1, 'mcq', 'សមភាព \(0 = 6\) មិនពិតជានិច្ច នាំឱ្យប្រព័ន្ធសមីការគ្មានចម្លើយ (សំណុំទទេ)។', 'ប្រព័ន្ធសមីការ', 'easy', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10805, 'ដោះស្រាយប្រព័ន្ធសមីការ \(\begin{cases} x + y = 11 \\ xy = 30 \end{cases}\)៖', NULL, '["\\((3, 8), \\; (8, 3)\\)", "\\((5, 6), \\; (6, 5)\\)", "\\((5, 5), \\; (6, 6)\\)", "\\((2, 15), \\; (15, 2)\\)"]', 1, NULL, 1, 'mcq', 'x, y ជាឫសនៃ \(t^2 - 11t + 30 = 0 \iff (t - 5)(t - 6) = 0 \implies t = 5, \; 6\)។', 'ប្រព័ន្ធសមីការ', 'easy', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10806, 'គេឱ្យប្រព័ន្ធ \(\begin{cases} x + y = 7 \\ xy = 12 \end{cases}\)។ គណនាតម្លៃ \(x^2 + y^2\)៖', NULL, '["\\(25\\)", "\\(24\\)", "\\(49\\)", "\\(37\\)"]', 0, NULL, 1, 'mcq', '\(x^2 + y^2 = (x + y)^2 - 2xy = 7^2 - 2(12) = 49 - 24 = 25\)។', 'ប្រព័ន្ធសមីការ', 'easy', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10807, 'គេឱ្យ \(x^2 + y^2 = 25\) និង \(xy = 12\) ចំពោះ \(x, y > 0\)។ រកតម្លៃ \(x + y\)៖', NULL, '["\\(5\\)", "\\(13\\)", "\\(7\\)", "\\(1\\)"]', 2, NULL, 1, 'mcq', '\((x + y)^2 = x^2 + y^2 + 2xy = 25 + 24 = 49 \implies x + y = \sqrt{49} = 7\)។', 'ប្រព័ន្ធសមីការ', 'easy', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10808, 'គេឱ្យប្រព័ន្ធ \(\begin{cases} x + 2y + 3z = 7 \\ 2x + 3y + z = 8 \\ 3x + y + 2z = 9 \end{cases}\)។ គណនា \(x + y + z\)៖', NULL, '["\\(4\\)", "\\(24\\)", "\\(8\\)", "\\(6\\)"]', 0, NULL, 1, 'mcq', 'បូកសមីការទាំងបី ៖ \(6x + 6y + 6z = 24 \implies 6(x + y + z) = 24 \implies x + y + z = 4\)។', 'ប្រព័ន្ធសមីការ', 'easy', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10809, 'ដោះស្រាយប្រព័ន្ធសមីការ \(\begin{cases} x - 3y = 0 \\ 2x + y = 14 \end{cases}\) នោះ \((x, y)\) គឺ៖', NULL, '["\\((6, 2)\\)", "\\((3, 1)\\)", "\\((9, 3)\\)", "\\((2, 6)\\)"]', 0, NULL, 1, 'mcq', '\(x = 3y \implies 2(3y) + y = 14 \implies 7y = 14 \implies y = 2 \implies x = 6\)។', 'ប្រព័ន្ធសមីការ', 'easy', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10810, 'ដោះស្រាយប្រព័ន្ធ \(\begin{cases} 3x - y = -6 \\ x + 5y = -2 \end{cases}\) នោះ \((x, y)\) គឺ៖', NULL, '["\\((-2, 2)\\)", "\\((1, -1)\\)", "\\((0, 6)\\)", "\\((-2, 0)\\)"]', 3, NULL, 1, 'mcq', '\(y = 3x + 6 \implies x + 5(3x + 6) = -2 \implies 16x = -32 \implies x = -2, \; y = 0\)។', 'ប្រព័ន្ធសមីការ', 'easy', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10811, 'រកតម្លៃ \(x\) នៃប្រព័ន្ធ \(\begin{cases} x + y + z = 13 \\ x + 2y - z = 7 \\ 3x - y + z = 23 \end{cases}\)៖', NULL, '["\\(7\\)", "\\(5\\)", "\\(2\\)", "\\(4\\)"]', 0, NULL, 2, 'mcq', 'បូក (1) + (2) ៖ \(2x + 3y = 20\)។ បូក (2) + (3) ៖ \(4x + y = 30\)។ ដោះស្រាយបាន \(x = 7, \; y = 2, \; z = 4\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10812, 'ដោះស្រាយប្រព័ន្ធ \(\begin{cases} x + y + z = 6 \\ 3x - y - 3z = 0 \\ x - 2y + 5z = 1 \end{cases}\) នោះ \((x, y, z)\) គឺ៖', NULL, '["\\((3, 2, 1)\\)", "\\((1, 2, 3)\\)", "\\((2, 1, 3)\\)", "\\((2, 3, 1)\\)"]', 3, NULL, 2, 'mcq', 'ដោះស្រាយប្រព័ន្ធរកបាន \(x = 2, \; y = 3, \; z = 1\)។ ផ្ទៀងផ្ទាត់ ៖ \(2 + 3 + 1 = 6\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10813, 'រកតម្លៃ \(m, n\) ដើម្បីឱ្យប្រព័ន្ធ \(\begin{cases} mx + ny = 8 \\ 5x + 3y = 4 \end{cases}\) មានឫសរាប់មិនអស់៖', NULL, '["\\(m = 5, \\; n = 3\\)", "\\(m = 10, \\; n = 3\\)", "\\(m = 8, \\; n = 4\\)", "\\(m = 10, \\; n = 6\\)"]', 3, NULL, 2, 'mcq', 'ប្រព័ន្ធមានឫសរាប់មិនអស់កាលណា \(\dfrac{m}{5} = \dfrac{n}{3} = \dfrac{8}{4} = 2 \implies m = 10, \; n = 6\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10814, 'រកតម្លៃ \(a\) ដើម្បីឱ្យប្រព័ន្ធ \(\begin{cases} 4x + 3y = 12 \\ 2x + ay = 5 \end{cases}\) គ្មានឫស៖', NULL, '["\\(a = -1.5\\)", "\\(a = 2\\)", "\\(a = 1.5\\)", "\\(a = 3\\)"]', 2, NULL, 2, 'mcq', 'ប្រព័ន្ធគ្មានឫសកាលណា \(\dfrac{4}{2} = \dfrac{3}{a} \neq \dfrac{12}{5} \implies 2 = \dfrac{3}{a} \implies a = 1.5\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10815, 'ដោះស្រាយប្រព័ន្ធសមីការ \(\begin{cases} y = x - 1 \\ x^2 + y^2 = 13 \end{cases}\)៖', NULL, '["\\((2, 1), \\; (-3, -4)\\)", "\\((3, 2), \\; (-2, -3)\\)", "\\((-3, -2), \\; (2, 3)\\)", "\\((3, 2), \\; (2, 3)\\)"]', 1, NULL, 2, 'mcq', 'ជំនួស y ៖ \(x^2 + (x - 1)^2 = 13 \implies 2x^2 - 2x - 12 = 0 \implies x = 3 \text{ ឬ } x = -2\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10816, 'ដោះស្រាយប្រព័ន្ធសមីការ \(\begin{cases} y = x^2 \\ x + y = 2 \end{cases}\)៖', NULL, '["\\((2, 0), \\; (0, 2)\\)", "\\((1, 1), \\; (-2, 4)\\)", "\\((-1, 1), \\; (-2, 4)\\)", "\\((1, 1), \\; (2, 4)\\)"]', 1, NULL, 2, 'mcq', '\(x^2 + x - 2 = 0 \iff (x - 1)(x + 2) = 0 \implies x = 1 \implies y = 1\) ឬ \(x = -2 \implies y = 4\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10817, 'ដោះស្រាយប្រព័ន្ធ \(\begin{cases} 2x + y = 5 \\ x^2 + y^2 = 25 \end{cases}\) នោះគូចម្លើយ \((x, y)\) គឺ៖', NULL, '["\\((1, 3), \\; (4, -3)\\)", "\\((0, 5), \\; (4, -3)\\)", "\\((5, 0), \\; (-3, 4)\\)", "\\((0, 5), \\; (3, -1)\\)"]', 1, NULL, 2, 'mcq', 'ជំនួស \(y = 5 - 2x\) ៖ \(x^2 + (5 - 2x)^2 = 25 \implies 5x^2 - 20x = 0 \implies x = 0 \text{ ឬ } x = 4\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10818, 'ដីចម្ការរាងចតុកោណកែងមួយមានបរិមាត្រ \(270\text{ m}\) និងផ្ទៃក្រឡា \(4\,284\text{ m}^2\)។ រកប្រវែងបណ្តោយ និងទទឹង៖', NULL, '["\\(84\\text{ m} \\text{ និង } 48\\text{ m}\\)", "\\(90\\text{ m} \\text{ និង } 45\\text{ m}\\)", "\\(80\\text{ m} \\text{ និង } 55\\text{ m}\\)", "\\(84\\text{ m} \\text{ និង } 51\\text{ m}\\)"]', 3, NULL, 2, 'mcq', '\(x + y = 135, \; xy = 4\,284 \implies t^2 - 135t + 4\,284 = 0\) មានឫស \(84 \text{ និង } 51\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10819, 'ត្រីកោណកែងមួយមានអុីប៉ូតេនុសប្រវែង \(13\text{ cm}\) និងផលបូកជ្រុងជាប់មុំកែងស្មើ \(17\text{ cm}\)។ រកប្រវែងជ្រុងជាប់មុំកែងទាំងពីរ៖', NULL, '["\\(11\\text{ cm} \\text{ និង } 6\\text{ cm}\\)", "\\(12\\text{ cm} \\text{ និង } 5\\text{ cm}\\)", "\\(9\\text{ cm} \\text{ និង } 8\\text{ cm}\\)", "\\(10\\text{ cm} \\text{ និង } 7\\text{ cm}\\)"]', 1, NULL, 2, 'mcq', '\(a + b = 17, \; a^2 + b^2 = 169 \implies 2ab = 17^2 - 169 = 120 \implies ab = 60\)។ ឫសនៃ \(t^2 - 17t + 60 = 0\) គឺ 12 និង 5។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10820, 'ដោះស្រាយប្រព័ន្ធសមីការ \(\begin{cases} \dfrac{1}{x} + \dfrac{1}{y} = 5 \\ \dfrac{1}{x} - \dfrac{1}{y} = 1 \end{cases}\) នោះ \((x, y)\) គឺ៖', NULL, '["\\(\\left(\\dfrac{1}{2}, \\; \\dfrac{1}{3}\\right)\\)", "\\(\\left(\\dfrac{1}{4}, \\; 1\\right)\\)", "\\(\\left(\\dfrac{1}{3}, \\; \\dfrac{1}{2}\\right)\\)", "\\((3, 2)\\)"]', 2, NULL, 2, 'mcq', 'បូកសមីការទាំងពីរ ៖ \(\dfrac{2}{x} = 6 \implies \dfrac{1}{x} = 3 \implies x = \dfrac{1}{3}\) និង \(\dfrac{1}{y} = 2 \implies y = \dfrac{1}{2}\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10821, 'ដោះស្រាយប្រព័ន្ធសមីការ \(\begin{cases} x - y = 3 \\ x^2 - y^2 = 21 \end{cases}\) នោះ \((x, y)\) គឺ៖', NULL, '["\\((5, 2)\\)", "\\((6, 3)\\)", "\\((4, 1)\\)", "\\((7, 4)\\)"]', 0, NULL, 2, 'mcq', '\(x^2 - y^2 = (x - y)(x + y) = 21 \implies 3(x + y) = 21 \implies x + y = 7\)។ រួមជាមួយ \(x - y = 3 \implies x = 5, \; y = 2\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10822, 'រកតម្លៃ \(y\) នៃប្រព័ន្ធ \(\begin{cases} x + 2y = 5 \\ y + 2z = -1 \\ z + 5x = 7 \end{cases}\)៖', NULL, '["\\(\\dfrac{5}{3}\\)", "\\(\\dfrac{4}{3}\\)", "\\(2\\)", "\\(-\\dfrac{4}{3}\\)"]', 0, NULL, 2, 'mcq', 'ដោះស្រាយប្រព័ន្ធរកបាន \(x = \dfrac{5}{3}, \; y = \dfrac{5}{3}, \; z = -\dfrac{4}{3}\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10823, 'គេឱ្យ \(x + y = 5\) និង \(xy = 6\)។ គណនាតម្លៃ \(x^3 + y^3\)៖', NULL, '["\\(45\\)", "\\(65\\)", "\\(35\\)", "\\(125\\)"]', 2, NULL, 2, 'mcq', '\(x^3 + y^3 = (x + y)^3 - 3xy(x + y) = 5^3 - 3(6)(5) = 125 - 90 = 35\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10824, 'ដោះស្រាយប្រព័ន្ធ \(\begin{cases} x + y = 25 \\ xy = 150 \end{cases}\) នោះគូចម្លើយ \((x, y)\) គឺ៖', NULL, '["\\((20, 5), \\; (5, 20)\\)", "\\((12, 13), \\; (13, 12)\\)", "\\((15, 10), \\; (10, 15)\\)", "\\((15, 15), \\; (10, 10)\\)"]', 2, NULL, 2, 'mcq', 'ឫសនៃ \(t^2 - 25t + 150 = 0 \iff (t - 15)(t - 10) = 0 \implies t = 15, \; 10\)។', 'ប្រព័ន្ធសមីការ', 'medium', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10825, 'ដោះស្រាយប្រព័ន្ធ \(\begin{cases} 3x + 2y = 6 \\ 9x^2 - 4y^2 = 108 \end{cases}\) នោះ \((x, y)\) គឺ៖', NULL, '["\\((2, 0)\\)", "\\((4, -3)\\)", "\\((3, -1.5)\\)", "\\((-4, 9)\\)"]', 1, NULL, 3, 'mcq', '\(9x^2 - 4y^2 = (3x - 2y)(3x + 2y) = 108 \implies (3x - 2y)(6) = 108 \implies 3x - 2y = 18\)។ បូកនឹង \(3x + 2y = 6 \implies 6x = 24 \implies x = 4, \; y = -3\)។', 'ប្រព័ន្ធសមីការ', 'hard', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10826, 'ត្រីកោណកែងមួយមានអុីប៉ូតេនុស \(41\text{ cm}\) និងផ្ទៃ \(180\text{ cm}^2\)។ រកប្រវែងជ្រុងមុំកែងទាំងពីរ៖', NULL, '["\\(30\\text{ cm} \\text{ និង } 12\\text{ cm}\\)", "\\(35\\text{ cm} \\text{ និង } 14\\text{ cm}\\)", "\\(40\\text{ cm} \\text{ និង } 9\\text{ cm}\\)", "\\(36\\text{ cm} \\text{ និង } 10\\text{ cm}\\)"]', 2, NULL, 3, 'mcq', '\(a^2 + b^2 = 41^2 = 1\,681, \; ab = 360 \implies (a+b)^2 = 2\,401 = 49^2, \; (a-b)^2 = 961 = 31^2 \implies a = 40, \; b = 9\)។', 'ប្រព័ន្ធសមីការ', 'hard', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10827, 'រកតម្លៃ \(m\) ដើម្បីឱ្យប្រព័ន្ធសមីការ \(\begin{cases} 3x + 7y = m \\ 2x + 5y = 20 \end{cases}\) មានឫសវិជ្ជមាន \(x > 0, \; y > 0\)៖', NULL, '["\\(20 < m < 40\\)", "\\(m > 30\\)", "\\(m < 28\\)", "\\(28 < m < 30\\)"]', 3, NULL, 3, 'mcq', 'គុណសមីការរកបាន \(x = 5m - 140, \; y = 60 - 2m\)។ លក្ខខណ្ឌវិជ្ជមាន ៖ \(5m - 140 > 0 \implies m > 28\) និង \(60 - 2m > 0 \implies m < 30\) នាំឱ្យ \(28 < m < 30\)។', 'ប្រព័ន្ធសមីការ', 'hard', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10828, 'គេឱ្យប្រព័ន្ធសមីការ \(\begin{cases} x + y = 3 \\ x^4 + y^4 = 17 \end{cases}\) លើចំនួនពិត។ គណនាតម្លៃ \(xy\)៖', NULL, '["\\(2\\)", "\\(3\\)", "\\(4\\)", "\\(1\\)"]', 0, NULL, 3, 'mcq', '\((x^2 + y^2)^2 - 2x^2y^2 = 17 \iff ((x+y)^2 - 2xy)^2 - 2(xy)^2 = 17 \iff (9 - 2P)^2 - 2P^2 = 17 \iff 2P^2 - 36P + 64 = 0 \iff P^2 - 18P + 32 = 0\)។ ដោយ \(P \le \frac{S^2}{4} = 2.25\) គេជ្រើស \(P = xy = 2\)។', 'ប្រព័ន្ធសមីការ', 'hard', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10829, 'រកតម្លៃ \(t\) នៃប្រព័ន្ធ 4 អថេរ \(\begin{cases} x + 2y + 3z + 4t = 30 \\ x - 2y + 3z + 4t = 22 \\ x + 2y - 3z + 4t = 12 \\ x + 2y + 3z - 4t = -2 \end{cases}\)៖', NULL, '["\\(4\\)", "\\(1\\)", "\\(2\\)", "\\(3\\)"]', 0, NULL, 3, 'mcq', 'យកសមីការ (1) ដកសមីការ (4) ៖ \(8t = 30 - (-2) = 32 \implies t = 4\)។', 'ប្រព័ន្ធសមីការ', 'hard', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10830, 'រកតម្លៃ \(k\) ដើម្បីឱ្យបន្ទាត់ \(y = 2x + k\) ប៉ះប៉ារ៉ាបូល \(y = x^2 + 6\) (ប្រព័ន្ធមានចម្លើយត្រួតគ្នា)៖', NULL, '["\\(5\\)", "\\(4\\)", "\\(6\\)", "\\(7\\)"]', 0, NULL, 3, 'mcq', 'សមីការអាប់ស៊ីស ៖ \(x^2 - 2x + (6 - k) = 0\)។ បន្ទាត់ប៉ះប៉ារ៉ាបូលកាលណា \(\Delta'' = 1 - (6 - k) = 0 \iff k - 5 = 0 \implies k = 5\)។', 'ប្រព័ន្ធសមីការ', 'hard', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10831, 'ពីរចំនួនមានផលគុណស្មើនឹង 12 ហើយផលបូកការេរបស់វាស្មើនឹង 25។ គូរចំនួនវិជ្ជមានទាំងពីរនោះគឺ៖', NULL, '["\\((12, 1) \text{ ឬ } (1, 12)\\)", "\\((5, 2) \text{ ឬ } (2, 5)\\)", "\\((4, 3) \text{ ឬ } (3, 4)\\)", "\\((6, 2) \text{ ឬ } (2, 6)\\)"]', 2, NULL, 3, 'mcq', '\(x^2 + y^2 = 25, \; xy = 12 \implies (x+y)^2 = 49 \implies x+y = 7\)។ ឫសនៃ \(t^2 - 7t + 12 = 0\) គឺ 4 និង 3។', 'ប្រព័ន្ធសមីការ', 'hard', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10832, 'ហាងកាហ្វេមួយលក់កាហ្វេ 3 ប្រភេទគឺ ប្រភេទ A, B និង C។ អតិថិជនបីក្រុមបានទិញដូចខាងក្រោម៖
- ក្រុមទី 1: 1 កែវ A, 1 កែវ B, 1 កែវ C អស់ប្រាក់ $6
- ក្រុមទី 2: 3 កែវ A, 2 កែវ B, 1 កែវ C អស់ប្រាក់ $11
- ក្រុមទី 3: 2 កែវ A, 1 កែវ B, 3 កែវ C អស់ប្រាក់ $13
តើតម្លៃកាហ្វេប្រភេទ A មួយកែវថ្លៃប៉ុន្មាន?', NULL, '["\\(\\$1.5\\)", "\\(\\$3\\)", "\\(\\$2.5\\)", "\\(\\$2\\)"]', 3, NULL, 3, 'mcq', 'តាង a, b, c ជាតម្លៃកែវនីមួយៗ ៖ \(\begin{cases} a + b + c = 6 \\ 3a + 2b + c = 11 \\ 2a + b + 3c = 13 \end{cases}\)។ ដោះស្រាយបាន \(a = 2, \; b = 3, \; c = 1\)។ ដូច្នេះប្រភេទ A ថ្លៃ $2។', 'ប្រព័ន្ធសមីការ', 'pisa', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10833, 'ក្រុមហ៊ុនដឹកជញ្ជូនមួយមានឡានដឹក 3 ប្រភេទ៖ តូច (ផ្ទុក 1 តោន), កណ្តាល (ផ្ទុក 2 តោន) និងធំ (ផ្ទុក 4 តោន)។ ក្រុមហ៊ុនមានឡានសរុប 18 គ្រឿង ដែលមានសមត្ថភាពផ្ទុកសរុប 44 តោន។ បើសរុបចំនួនឡានតូចនិងកណ្តាលស្មើនឹង 2 ដងនៃចំនួនឡានធំ តើក្រុមហ៊ុនមានឡានធំប៉ុន្មានគ្រឿង?', NULL, '["\\(5 \text{ គ្រឿង}\\)", "\\(8 \text{ គ្រឿង}\\)", "\\(6 \text{ គ្រឿង}\\)", "\\(4 \text{ គ្រឿង}\\)"]', 2, NULL, 3, 'mcq', 'តាង x, y, z ជាចំនួនឡានតូច កណ្តាល ធំ ៖ \(\begin{cases} x + y + z = 18 \\ x + 2y + 4z = 44 \\ x + y = 2z \end{cases}\)។ ជំនួស x+y=2z ក្នុងទី 1 ៖ \(2z + z = 18 \implies 3z = 18 \implies z = 6\) គ្រឿង។', 'ប្រព័ន្ធសមីការ', 'pisa', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10834, 'គម្រោងថាមពលពន្លឺព្រះអាទិត្យមួយត្រូវការដំឡើងផ្ទាំងសូឡាចំនួន 20 ផ្ទាំងដែលមានកម្លាំងពីរកម្រិត គឺ 300W និង 450W ដើម្បីទទួលបានថាមពលសរុប 7\,200W។ តើត្រូវប្រើផ្ទាំង 450W ចំនួនប៉ុន្មាន?', NULL, '["\\(12 \text{ ផ្ទាំង}\\)", "\\(10 \text{ ផ្ទាំង}\\)", "\\(8 \text{ ផ្ទាំង}\\)", "\\(6 \text{ ផ្ទាំង}\\)"]', 2, NULL, 3, 'mcq', '\(\begin{cases} x + y = 20 \\ 300x + 450y = 7\,200 \end{cases} \iff \begin{cases} 300x + 300y = 6\,000 \\ 300x + 450y = 7\,200 \end{cases} \implies 150y = 1\,200 \implies y = 8\) ផ្ទាំង។', 'ប្រព័ន្ធសមីការ', 'pisa', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10835, 'កសិករម្នាក់មានរបងលួសប្រវែង 100 ម៉ែត្រសម្រាប់ព័ទ្ធដីចម្ការរាងចតុកោណកែងមួយដែលមានផ្ទៃក្រឡា 600 ម៉ែត្រការ៉េ។ តើប្រវែងបណ្តោយនៃចម្ការនោះស្មើនឹងប៉ុន្មានម៉ែត្រ?', NULL, '["\\(35\\text{ m}\\)", "\\(40\\text{ m}\\)", "\\(25\\text{ m}\\)", "\\(30\\text{ m}\\)"]', 3, NULL, 3, 'mcq', 'កន្លះបរិមាត្រ \(x + y = 50\) និងផ្ទៃ \(xy = 600\)។ សមីការ \(t^2 - 50t + 600 = 0\) មានឫស 30 និង 20។ ដូច្នេះបណ្តោយគឺ 30 ម៉ែត្រ។', 'ប្រព័ន្ធសមីការ', 'pisa', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10836, 'មន្ទីរពិសោធន៍មួយចង់លាយសូលុយស្យុងអាស៊ីតពីរកម្រិត គឺកំហាប់ 20% និងកំហាប់ 50% ដើម្បីទទួលបានសូលុយស្យុងថ្មីកំហាប់ 30% ចំនួន 60 លីត្រ។ តើត្រូវប្រើសូលុយស្យុង 20% ចំនួនប៉ុន្មានលីត្រ?', NULL, '["\\(40 \text{ លីត្រ}\\)", "\\(30 \text{ លីត្រ}\\)", "\\(20 \text{ លីត្រ}\\)", "\\(45 \text{ លីត្រ}\\)"]', 0, NULL, 3, 'mcq', '\(\begin{cases} x + y = 60 \\ 0.20x + 0.50y = 0.30(60) = 18 \end{cases} \implies 0.20x + 0.50(60 - x) = 18 \implies -0.30x = -12 \implies x = 40\) លីត្រ។', 'ប្រព័ន្ធសមីការ', 'pisa', 1, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10837, 'ដោះស្រាយប្រព័ន្ធសមីការដឺក្រេទី 1 មានពីរអញ្ញាត ៖
\(\begin{cases} 2x + 3y = 13 \\ 5x - 3y = 8 \end{cases}\)', NULL, '[]', 0, NULL, 5, 'writing', 'បូកអង្គនិងអង្គនៃសមីការទាំងពីរដើម្បីបំបាត់ y ៖ \((2x + 3y) + (5x - 3y) = 13 + 8 \implies 7x = 21\) (2 ពិន្ទុ)
ទាញរកតម្លៃ \(x = \dfrac{21}{7} = 3\) (1 ពិន្ទុ)
ជំនួស \(x = 3\) ក្នុងសមីការទីមួយ ៖ \(2(3) + 3y = 13 \implies 6 + 3y = 13 \implies 3y = 7 \implies y = \dfrac{7}{3}\) (1 ពិន្ទុ)
សន្និដ្ឋានគូចម្លើយនៃប្រព័ន្ធគឺ \(\left(x = 3, \; y = \dfrac{7}{3}\right)\) (1 ពិន្ទុ)', 'ប្រព័ន្ធសមីការ', 'easy', 0, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
