INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10842, 'ពិភាក្សាប្រព័ន្ធសមីការទៅតាមតម្លៃប៉ារ៉ាម៉ែត្រ \(a\) ៖
\(\begin{cases} ax + y = 1 \\ x + ay = 1 \end{cases}\)', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាដេទែមីណង់ \(D = a(a) - 1(1) = a^2 - 1 = (a - 1)(a + 1)\) (1 ពិន្ទុ)
ករណី \(a \neq \pm 1\) ៖ ប្រព័ន្ធមានចម្លើយទោល \(x = y = \dfrac{1}{a + 1}\) (1 ពិន្ទុ)
ករណី \(a = 1\) ៖ សមីការទាំងពីរក្លាយជា \(x + y = 1\) ប្រព័ន្ធមានឫសរាប់មិនអស់ (1 ពិន្ទុ)
ករណី \(a = -1\) ៖ ប្រព័ន្ធក្លាយជា \(\begin{cases} -x + y = 1 \\ x - y = 1 \end{cases}\) បូកបញ្ចូលគ្នាបាន \(0 = 2\) មិនពិត នាំឱ្យប្រព័ន្ធគ្មានឫស \(S = \emptyset\) (2 ពិន្ទុ)', 'ប្រព័ន្ធសមីការ', 'hard', 0, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10843, 'ដោះស្រាយប្រព័ន្ធសមីការ ៖
\(\begin{cases} \dfrac{1}{x} + \dfrac{2}{y} + \dfrac{1}{z} = 9 \\ \dfrac{1}{x} - \dfrac{2}{y} + \dfrac{3}{z} = 9 \\ \dfrac{1}{x} + \dfrac{1}{y} - \dfrac{3}{z} = -9 \end{cases}\)', NULL, '[]', 0, NULL, 5, 'writing', 'តាងអញ្ញាតជំនួយ \(u = \dfrac{1}{x}, \; v = \dfrac{1}{y}, \; w = \dfrac{1}{z}\) (លក្ខខណ្ឌ \(x, y, z \neq 0\)) (1 ពិន្ទុ)
សរសេរប្រព័ន្ធលីនេអ៊ែរជាទម្រង់ \(u, v, w\) (1 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធរកបាន \(u = 1, \; v = 3, \; w = 2\) (2 ពិន្ទុ)
ទាញរក \(x = 1, \; y = \dfrac{1}{3}, \; z = \dfrac{1}{2}\) រួចសន្និដ្ឋានចម្លើយ (1 ពិន្ទុ)', 'ប្រព័ន្ធសមីការ', 'hard', 0, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10844, 'ត្រីកោណកែងមួយមានបរិមាត្រ \(60\text{ cm}\) និងផ្ទៃក្រឡា \(120\text{ cm}^2\)។ រកប្រវែងជ្រុងទាំងបីនៃត្រីកោណនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង a, b ជាជ្រុងមុំកែង និង c ជាអុីប៉ូតេនុស ៖ \(a + b + c = 60\) និង \(\dfrac{1}{2}ab = 120 \implies ab = 240\) (1 ពិន្ទុ)
តាមពីតាក័រ \(c^2 = a^2 + b^2 = (a + b)^2 - 2ab = (60 - c)^2 - 480\) (1 ពិន្ទុ)
ពន្លាតសមីការ ៖ \(c^2 = 3\,600 - 120c + c^2 - 480 \implies 120c = 3\,120 \implies c = 26	ext{ cm}\) (1 ពិន្ទុ)
ទាញបាន \(a + b = 34\) និង \(ab = 240\) ដោះស្រាយបាន \(a = 24, \; b = 10\) (1 ពិន្ទុ)
សន្និដ្ឋានប្រវែងជ្រុងទាំងបីគឺ \(10\text{ cm}, \; 24\text{ cm}, \; 26\text{ cm}\) (1 ពិន្ទុ)', 'ប្រព័ន្ធសមីការ', 'hard', 0, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10845, 'ដោះស្រាយប្រព័ន្ធសមីការស៊ីមេទ្រី ៖
\(\begin{cases} x^2 + y^2 = 13 \\ x + y + xy = 11 \end{cases}\)', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(S = x + y\) និង \(P = xy\)។ សរសេរ \(x^2 + y^2 = S^2 - 2P = 13\) (1 ពិន្ទុ)
តាមសមីការទីពីរ \(S + P = 11 \implies P = 11 - S\) (1 ពិន្ទុ)
ជំនួស P ៖ \(S^2 - 2(11 - S) = 13 \iff S^2 + 2S - 35 = 0 \implies S = 5 	ext{ ឬ } S = -7\) (1 ពិន្ទុ)
បើ \(S = 5 \implies P = 6\) រកបាន \((x, y) = (2, 3), \; (3, 2)\) (1 ពិន្ទុ)
បើ \(S = -7 \implies P = 18\) សមីការ \(t^2 + 7t + 18 = 0\) មាន \(\Delta < 0\) គ្មានឫសពិត។ សន្និដ្ឋានចម្លើយ (1 ពិន្ទុ)', 'ប្រព័ន្ធសមីការ', 'hard', 0, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10846, 'សាលារៀនមួយជួលរថយន្តពីរប្រភេទសម្រាប់ដំណើរកម្សាន្តសិស្ស៖
- រថយន្តធំ (ប្រភេទ A) ផ្ទុកបាន 45 នាក់ តម្លៃជួល $80 ក្នុងមួយថ្ងៃ
- រថយន្តតូច (ប្រភេទ B) ផ្ទុកបាន 30 នាក់ តម្លៃជួល $55 ក្នុងមួយថ្ងៃ
សាលាត្រូវការដឹកសិស្សសរុប 390 នាក់ និងគ្រូ ដោយប្រើរថយន្តសរុប 10 គ្រឿង ហើយកៅអីទាំងអស់ត្រូវពេញល្មម។
ក. រកចំនួនរថយន្តប្រភេទ A និងប្រភេទ B ដែលត្រូវជួល។
ខ. គណនាថ្លៃជួលសរុបដែលសាលាត្រូវចំណាយ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង x ជាចំនួនឡានប្រភេទ A និង y ជាចំនួនឡានប្រភេទ B ៖ បង្កើតប្រព័ន្ធ \(\begin{cases} x + y = 10 \\ 45x + 30y = 390 \end{cases}\) (1 ពិន្ទុ)
គុណសមីការទី 1 នឹង 30 ៖ \(30x + 30y = 300\) (1 ពិន្ទុ)
ដកសមីការទាំងពីរ ៖ \(15x = 90 \implies x = 6\) រថយន្តធំ និង \(y = 10 - 6 = 4\) រថយន្តតូច (1 ពិន្ទុ)
គណនាថ្លៃជួលសរុប ៖ \(6 	imes 80 + 4 	imes 55 = 480 + 220 = 700\) ដុល្លារ (1 ពិន្ទុ)
សរសេរសេចក្តីសន្និដ្ឋានពេញលេញ (1 ពិន្ទុ)', 'ប្រព័ន្ធសមីការ', 'pisa', 0, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10847, 'អ្នកជំនាញអាហារូបត្ថម្ភរៀបចំរបបអាហារសម្រាប់អត្តពលិកដោយប្រើប្រភពអាហារ 3 មុខ (X, Y, Z) ដើម្បីបំពេញតម្រូវការប្រចាំថ្ងៃ៖
- ប្រូតេអ៊ីន ៖ X ផ្តល់ 20g, Y ផ្តល់ 10g, Z ផ្តល់ 10g (ត្រូវការសរុប 80g)
- កាបូអ៊ីដ្រាត ៖ X ផ្តល់ 10g, Y ផ្តល់ 30g, Z ផ្តល់ 20g (ត្រូវការសរុប 130g)
- ជាតិខ្លាញ់ ៖ X ផ្តល់ 5g, Y ផ្តល់ 5g, Z ផ្តល់ 15g (ត្រូវការសរុប 55g)
គណនាចំនួនចំណែកនៃអាហារនីមួយៗ (x, y, z) ដែលត្រូវទទួលទាន។', NULL, '[]', 0, NULL, 5, 'writing', 'បង្កើតប្រព័ន្ធសមីការ 3 អញ្ញាត ៖
\(\begin{cases} 20x + 10y + 10z = 80 \iff 2x + y + z = 8 \\ 10x + 30y + 20z = 130 \iff x + 3y + 2z = 13 \\ 5x + 5y + 15z = 55 \iff x + y + 3z = 11 \end{cases}\) (2 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធលីនេអ៊ែររកបាន x = 2 ចំណែកនៃអាហារ X (1 ពិន្ទុ)
រកបាន y = 3 ចំណែកនៃអាហារ Y និង z = 2 ចំណែកនៃអាហារ Z (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់គ្រប់សមីការនិងសរសេរសេចក្តីសន្និដ្ឋាន (1 ពិន្ទុ)', 'ប្រព័ន្ធសមីការ', 'pisa', 0, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10848, 'រោងចក្រផលិតសម្ភារៈមួយផលិតកៅអីឈើពីរម៉ូដគឺ ម៉ូដធម្មតា និងម៉ូដប្រណីត៖
- ម៉ូដធម្មតាប្រើឈើ 2 ម៉ែត្រ និងចំណាយពេលដំឡើង 3 ម៉ោង
- ម៉ូដប្រណីតប្រើឈើ 3 ម៉ែត្រ និងចំណាយពេលដំឡើង 5 ម៉ោង
ក្នុងមួយសប្តាហ៍ រោងចក្រប្រើឈើសរុប 160 ម៉ែត្រ និងកម្លាំងពលកម្មសរុប 250 ម៉ោង។
ក. កំណត់ចំនួនកៅអីម៉ូដនីមួយៗដែលរោងចក្រផលិតបានក្នុងមួយសប្តាហ៍។
ខ. បើកៅអីធម្មតាចំណេញ $15 ហើយកៅអីប្រណីតចំណេញ $25 រកប្រាក់ចំណេញសរុប។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង x ជាចំនួនកៅអីធម្មតា និង y ជាចំនួនកៅអីប្រណីត ៖ \(\begin{cases} 2x + 3y = 160 \\ 3x + 5y = 250 \end{cases}\) (1 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធ ៖ គុណសមីការ (1) នឹង 3 និង (2) នឹង 2 ៖ \(6x + 9y = 480\) និង \(6x + 10y = 500\) (1 ពិន្ទុ)
ទាញរក \(y = 20\) កៅអីប្រណីត និង \(2x + 60 = 160 \implies x = 50\) កៅអីធម្មតា (1 ពិន្ទុ)
គណនាប្រាក់ចំណេញសរុប ៖ \(50(15) + 20(25) = 750 + 500 = 1\,250\) ដុល្លារ (1 ពិន្ទុ)
សរសេរសេចក្តីសន្និដ្ឋាន (1 ពិន្ទុ)', 'ប្រព័ន្ធសមីការ', 'pisa', 0, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10849, 'វិស្វករស្ពានមួយបានរចនាខ្សែខ្សែកាបព្យួររាងប៉ារ៉ាបូលដែលមានសមីការ \(y = 0.01x^2 + 5\) និងធ្នឹមទ្រទ្រង់ត្រង់ដែលមានសមីការ \(y = 0.2x + 5\) (គិតជាម៉ែត្រ)។
ក. ដោះស្រាយប្រព័ន្ធសមីការដើម្បីរកចំណុចប្រសព្វរវាងខ្សែខ្សែកាបនិងធ្នឹម។
ខ. គណនាចម្ងាយរវាងចំណុចប្រសព្វទាំងពីរនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'បង្កើតសមីការអាប់ស៊ីស ៖ \(0.01x^2 + 5 = 0.2x + 5 \iff 0.01x^2 - 0.2x = 0\) (1 ពិន្ទុ)
ដាក់ជាផលគុណកត្តា ៖ \(x(0.01x - 0.2) = 0 \implies x_1 = 0 	ext{ ឬ } x_2 = 20	ext{ m}\) (1 ពិន្ទុ)
គណនាកូអរដោនេចំណុចប្រសព្វ ៖ \(A(0, 5)\) និង \(B(20, 9)\) (1 ពិន្ទុ)
គណនាចម្ងាយរវាង A និង B ៖ \(AB = \sqrt{(20 - 0)^2 + (9 - 5)^2} = \sqrt{400 + 16} = \sqrt{416} \approx 20.396	ext{ m}\) (1 ពិន្ទុ)
សរសេរសេចក្តីសន្និដ្ឋាន (1 ពិន្ទុ)', 'ប្រព័ន្ធសមីការ', 'pisa', 0, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10850, 'ក្រុមហ៊ុនទូរគមនាគមន៍មួយផ្តល់កញ្ចប់សេវាអ៊ីនធឺណិតពីរប្រភេទ៖
- កញ្ចប់ A ៖ បង់ថ្លៃសេវាថេរ $10 ក្នុងមួយខែ និងគិត $0.50 ក្នុង 1 GB
- កញ្ចប់ B ៖ បង់ថ្លៃសេវាថេរ $2 ក្នុងមួយខែ និងគិត $1.50 ក្នុង 1 GB សម្រាប់លើសពី 5 GB ដំបូងដោយឥតគិតថ្លៃ
ក. សរសេរសមីការចំណាយប្រចាំខែ \(y\) ជាអនុគមន៍នៃទំហំទិន្នន័យ \(x\) (GB) ចំពោះ \(x \ge 5\)។
ខ. រកទំហំទិន្នន័យ x ដែលធ្វើឱ្យតម្លៃនៃកញ្ចប់ទាំងពីរស្មើគ្នា។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរសមីការកញ្ចប់ A ៖ \(y_A = 10 + 0.5x\) (1 ពិន្ទុ)
សរសេរសមីការកញ្ចប់ B ៖ \(y_B = 2 + 1.5(x - 5) = 1.5x - 5.5\) (1 ពិន្ទុ)
បង្កើតសមីការស្មើគ្នា ៖ \(10 + 0.5x = 1.5x - 5.5\) (1 ពិន្ទុ)
ដោះស្រាយសមីការ ៖ \(x = 15.5	ext{ GB}\) (1 ពិន្ទុ)
សរសេរសេចក្តីសន្និដ្ឋាននិងការណែនាំដល់អតិថិជន (1 ពិន្ទុ)', 'ប្រព័ន្ធសមីការ', 'pisa', 0, '10', 'ប្រព័ន្ធសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10901, 'ចំពោះ \(a > b\) និង \(c < 0\) តើវិសមភាពណាត្រឹមត្រូវ?', NULL, '["\\(a + c < b + c\\)", "\\(ac < bc\\)", "\\(ac > bc\\)", "\\(ac = bc\\)"]', 1, NULL, 1, 'mcq', 'នៅពេលគុណ ឬចែកអង្គទាំងពីរនៃវិសមភាពនឹងចំនួនអវិជ្ជមាន ទិសដៅនៃវិសមភាពត្រូវតែប្តូរច្រាសមកវិញ។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'easy', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10902, 'ដោះស្រាយវិសមីការ \(15 + 2x > -11\)៖', NULL, '["\\(x > -26\\)", "\\(x > -13\\)", "\\(x > 2\\)", "\\(x < -13\\)"]', 1, NULL, 1, 'mcq', '\(2x > -11 - 15 \implies 2x > -26 \implies x > -13\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'easy', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10903, 'ដោះស្រាយវិសមីការ \(\dfrac{2x - 1}{3} \ge 5\)៖', NULL, '["\\(x \\ge 7\\)", "\\(x \\ge 16\\)", "\\(x \\le 8\\)", "\\(x \\ge 8\\)"]', 3, NULL, 1, 'mcq', '\(2x - 1 \ge 15 \implies 2x \ge 16 \implies x \ge 8\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'easy', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10904, 'រកសំណុំចម្លើយនៃប្រព័ន្ធ \(\begin{cases} 2x - 1 > 1 \\ 3x - 2 \le 10 \end{cases}\)៖', NULL, '["\\([1, 4]\\)", "\\((1, 4)\\)", "\\((1, 4] \text{ ឬ } 1 < x \\le 4\\)", "\\([1, 4)\\)"]', 2, NULL, 1, 'mcq', '\(2x > 2 \implies x > 1\) និង \(3x \le 12 \implies x \le 4\)។ ប្រសព្វគឺ \(1 < x \le 4\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'easy', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10905, 'រកសំណុំចម្លើយនៃប្រព័ន្ធ \(\begin{cases} x + 3 \ge 1 \\ 2x - 5 < 1 \end{cases}\)៖', NULL, '["\\([-2, 3]\\)", "\\((-2, 3]\\)", "\\((-2, 3)\\)", "\\([-2, 3) \text{ ឬ } -2 \\le x < 3\\)"]', 3, NULL, 1, 'mcq', '\(x \ge -2\) និង \(2x < 6 \implies x < 3\) នាំឱ្យ \(-2 \le x < 3\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'easy', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10906, 'ដោះស្រាយវិសមីការ \(x^2 - 5x + 6 \le 0\)៖', NULL, '["\\([2, 3] \text{ ឬ } 2 \\le x \\le 3\\)", "\\([-3, -2]\\)", "\\((2, 3)\\)", "\\((-\\infty, 2] \\cup [3, +\\infty)\\)"]', 0, NULL, 1, 'mcq', 'សមីការ \(x^2 - 5x + 6 = 0\) មានឫស \(x = 2, \; 3\)។ ដោយ \(a = 1 > 0\) កន្សោមអវិជ្ជមានក្នុងចន្លោះឫស \([2, 3]\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'easy', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10907, 'ដោះស្រាយវិសមីការ \(x^2 + 1 < 0\) លើសំណុំចំនួនពិត \(\mathbb{R}\)៖', NULL, '["\\(S = \\emptyset \\quad (\\text{គ្មានចម្លើយ})\\)", "\\(\\mathbb{R}\\)", "\\(x > 1\\)", "\\(x < -1\\)"]', 0, NULL, 1, 'mcq', 'ចំពោះគ្រប់ \(x \in \mathbb{R}, \; x^2 \ge 0 \implies x^2 + 1 \ge 1 > 0\)។ មិនអាចតូចជាង 0 ឡើយ។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'easy', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10908, 'ចំពោះត្រីធា \(f(x) = ax^2 + bx + c\) ដែលមាន \(a > 0\) និង \(\Delta > 0\) (មានឫស \(x_1 < x_2\))។ តើ \(f(x) < 0\) នៅពេលណា?', NULL, '["\\(x_1 < x < x_2 \\quad (\text{ក្នុងចន្លោះឫស})\\)", "\\(x \\ge x_2\\)", "\\(x < x_1 \text{ ឬ } x > x_2\\)", "\\(x \\le x_1\\)"]', 0, NULL, 1, 'mcq', 'ក្បួនសញ្ញាត្រីធាដឺក្រេទី 2 ៖ ក្នុងចន្លោះឫសសញ្ញាផ្ទុយ a (អវិជ្ជមាន) និងក្រៅចន្លោះឫសសញ្ញាដូច a។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'easy', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10909, 'ដោះស្រាយវិសមីការ \(|x| \le 5\)៖', NULL, '["\\(x \\le 5\\)", "\\([-5, 5] \text{ ឬ } -5 \\le x \\le 5\\)", "\\(x \\ge -5\\)", "\\((-\\infty, -5] \\cup [5, +\\infty)\\)"]', 1, NULL, 1, 'mcq', 'តាមនិយមន័យ \(|x| \le a \iff -a \le x \le a\)។ ដូច្នេះ \(-5 \le x \le 5\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'easy', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10910, 'ចំពោះពីរចំនួនពិតវិជ្ជមាន \(a, b \ge 0\) គេបាន \(\dfrac{a+b}{2} \ge \sqrt{ab}\)។ តើសមភាពកើតមាននៅពេលណា?', NULL, '["\\(a + b = 1\\)", "\\(a > b\\)", "\\(ab = 1\\)", "\\(a = b\\)"]', 3, NULL, 1, 'mcq', 'សមភាព \(\dfrac{a+b}{2} = \sqrt{ab}\) កើតឡើងលុះត្រាតែ \((\sqrt{a} - \sqrt{b})^2 = 0 \iff a = b\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'easy', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10911, 'ដោះស្រាយវិសមីការ \(5(x - 3) - 7x \ge 4(x - 3) + 9\)៖', NULL, '["\\(x \\ge -2\\)", "\\(x \\ge 2\\)", "\\(x \\le -2\\)", "\\(x \\le 2\\)"]', 2, NULL, 2, 'mcq', '\(5x - 15 - 7x \ge 4x - 12 + 9 \iff -2x - 15 \ge 4x - 3 \iff -6x \ge 12 \iff x \le -2\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10912, 'ដោះស្រាយវិសមីការ \(x^2 - 4x - 5 > 0\)៖', NULL, '["\\((-1, 5)\\)", "\\((-\\infty, -5) \\cup (1, +\\infty)\\)", "\\((-\\infty, -1) \\cup (5, +\\infty)\\)", "\\([-1, 5]\\)"]', 2, NULL, 2, 'mcq', 'ឫសគឺ \(x = -1, \; 5\)។ ដោយ \(a = 1 > 0\) កន្សោមវិជ្ជមាននៅក្រៅចន្លោះឫស។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10913, 'ដោះស្រាយវិសមីការ \(x^2 + 4x + 4 > 0\)៖', NULL, '["\\(\\mathbb{R}\\)", "\\(S = \\emptyset\\)", "\\(\\mathbb{R} \\setminus \\{-2\\} \\quad (\\text{គ្រប់ } x \\neq -2)\\)", "\\(x > -2\\)"]', 2, NULL, 2, 'mcq', '\((x + 2)^2 > 0\) ពិតចំពោះគ្រប់ \(x \neq -2\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10914, 'ដោះស្រាយវិសមីការ \(|2x - 3| < 5\)៖', NULL, '["\\((-4, 1)\\)", "\\([-1, 4]\\)", "\\((-1, 4) \text{ ឬ } -1 < x < 4\\)", "\\((1, 4)\\)"]', 2, NULL, 2, 'mcq', '\(-5 < 2x - 3 < 5 \iff -2 < 2x < 8 \iff -1 < x < 4\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10915, 'ដោះស្រាយវិសមីការ \(|x - 2| \ge 3\)៖', NULL, '["\\(x \\le 1 \text{ ឬ } x \\ge 5\\)", "\\(x \\le -1 \\quad \text{ឬ} \\quad x \\ge 5\\)", "\\(x \\ge 5\\)", "\\(-1 \\le x \\le 5\\)"]', 1, NULL, 2, 'mcq', '\(x - 2 \le -3 \implies x \le -1\) ឬ \(x - 2 \ge 3 \implies x \ge 5\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10916, 'ដោះស្រាយវិសមីការ \(|3x + 1| > 7\)៖', NULL, '["\\(x > 2\\)", "\\(x < -\\dfrac{8}{3} \\quad \\text{ឬ} \\quad x > 2\\)", "\\(-\\dfrac{8}{3} < x < 2\\)", "\\(x < -2 \\text{ ឬ } x > \\dfrac{8}{3}\\)"]', 1, NULL, 2, 'mcq', '\(3x + 1 < -7 \implies x < -\frac{8}{3}\) ឬ \(3x + 1 > 7 \implies x > 2\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10917, 'ចំពោះ \(x > 0\) តើតម្លៃអប្បបរមានៃកន្សោម \(A = x + \dfrac{1}{x}\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(2\\)", "\\(4\\)", "\\(1\\)", "\\(0\\)"]', 0, NULL, 2, 'mcq', 'តាមវិសមភាព AM-GM ៖ \(\dfrac{x + \frac{1}{x}}{2} \ge \sqrt{x \cdot \frac{1}{x}} = 1 \implies x + \frac{1}{x} \ge 2\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10918, 'រកចំនួនគត់វិជ្ជមាន \(n\) តូចបំផុតដែលផ្ទៀងផ្ទាត់វិសមីការ \(3n - 7 > 20\)៖', NULL, '["\\(10\\)", "\\(9\\)", "\\(8\\)", "\\(11\\)"]', 0, NULL, 2, 'mcq', '\(3n > 27 \implies n > 9\)។ ចំនួនគត់វិជ្ជមានតូចបំផុតគឺ \(n = 10\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10919, 'ដោះស្រាយប្រព័ន្ធវិសមីការ \(\begin{cases} 4x - 5 < 2x + 7 \\ 3(x + 1) \ge x - 1 \end{cases}\) នោះចម្លើយគឺ៖', NULL, '["\\((-2, 6]\\)", "\\((-2, 6)\\)", "\\([-2, 6) \text{ ឬ } -2 \\le x < 6\\)", "\\([-2, 6]\\)"]', 2, NULL, 2, 'mcq', '\(2x < 12 \implies x < 6\) និង \(2x \ge -4 \implies x \ge -2\) នាំឱ្យ \([-2, 6)\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10920, 'ដោះស្រាយវិសមីការ \(-2x^2 + 5x - 2 \ge 0\)៖', NULL, '["\\(\\left(-\\infty, \\dfrac{1}{2}\\right] \\cup [2, +\\infty)\\)", "\\(\\left[\\dfrac{1}{2}, \\; 2\\right]\\)", "\\([-2, -0.5]\\)", "\\(\\left(\\dfrac{1}{2}, \\; 2\\right)\\)"]', 1, NULL, 2, 'mcq', 'គុណនឹង -1 ៖ \(2x^2 - 5x + 2 \le 0 \implies (2x - 1)(x - 2) \le 0 \implies \dfrac{1}{2} \le x \le 2\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10921, 'ចំពោះ \(x > 0\) តើតម្លៃអប្បបរមានៃកន្សោម \(B = 4x + \dfrac{9}{x}\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(10\\)", "\\(13\\)", "\\(12\\)", "\\(6\\)"]', 2, NULL, 2, 'mcq', 'តាម AM-GM ៖ \(4x + \dfrac{9}{x} \ge 2\sqrt{4x \cdot \dfrac{9}{x}} = 2\sqrt{36} = 12\)។ សមភាពកើតពេល \(4x = \frac{9}{x} \implies x = 1.5\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10922, 'ដោះស្រាយវិសមីការពីរជាន់ \(-3 \le 2x + 1 \le 9\) នោះសំណុំចម្លើយគឺ៖', NULL, '["\\([-2, 5]\\)", "\\([-1, 4]\\)", "\\((-2, 4)\\)", "\\([-2, 4]\\)"]', 3, NULL, 2, 'mcq', '\(-3 - 1 \le 2x \le 9 - 1 \iff -4 \le 2x \le 8 \iff -2 \le x \le 4\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10923, 'ដោះស្រាយវិសមីការ \(|x - 1| \le |x + 3|\)៖', NULL, '["\\(x \\ge -1\\)", "\\(x \\le -1\\)", "\\(x \\ge 1\\)", "\\(x \\le 2\\)"]', 0, NULL, 2, 'mcq', 'លើកជាការេ ៖ \((x - 1)^2 \le (x + 3)^2 \iff x^2 - 2x + 1 \le x^2 + 6x + 9 \iff -8x \le 8 \iff x \ge -1\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10924, 'តើមានចំនួនគត់ \(x\) ប៉ុន្មានដែលផ្ទៀងផ្ទាត់វិសមីការ \(x^2 - 3x - 10 < 0\)?', NULL, '["\\(7\\)", "\\(5\\)", "\\(6\\)", "\\(8\\)"]', 2, NULL, 2, 'mcq', '\((x - 5)(x + 2) < 0 \iff -2 < x < 5\)។ ចំនួនគត់គឺ \(\{-1, 0, 1, 2, 3, 4\}\) មានចំនួន 6។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10925, 'ដោះស្រាយវិសមីការសនិទាន \(\dfrac{x - 2}{x + 1} \le 0\)៖', NULL, '["\\([-1, 2]\\)", "\\((-1, 2] \text{ ឬ } -1 < x \\le 2\\)", "\\((-1, 2)\\)", "\\((-\\infty, -1) \\cup [2, +\\infty)\\)"]', 1, NULL, 3, 'mcq', 'ភាគបែង \(x + 1 \neq 0 \implies x \neq -1\)។ កន្សោមអវិជ្ជមានក្នុងចន្លោះឫស \(-1 < x \le 2\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'hard', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10926, 'រកតម្លៃ \(m\) ដើម្បីឱ្យវិសមីការ \(x^2 - 2mx + (m + 6) > 0\) ពិតចំពោះគ្រប់ចំនួនពិត \(x \in \mathbb{R}\)៖', NULL, '["\\(-3 < m < 2\\)", "\\(m > 3 \text{ ឬ } m < -2\\)", "\\(-2 < m < 3\\)", "\\(m < 3\\)"]', 2, NULL, 3, 'mcq', 'វិសមីការពិតជានិច្ចកាលណា \(a = 1 > 0 \text{ និង } \Delta'' = m^2 - (m + 6) < 0 \iff (m - 3)(m + 2) < 0 \iff -2 < m < 3\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'hard', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10927, 'ដោះស្រាយវិសមីការ \(|x + 1| + |x - 3| \ge 6\)៖', NULL, '["\\(x \\le -2 \\quad \text{ឬ} \\quad x \\ge 4\\)", "\\(x \\ge 4\\)", "\\(-2 \\le x \\le 4\\)", "\\(x \\le -1 \text{ ឬ } x \\ge 3\\)"]', 0, NULL, 3, 'mcq', 'ចែកជា 3 ចន្លោះ ៖ បើ \(x \le -1 \implies -2x + 2 \ge 6 \implies x \le -2\)។ បើ \(x \ge 3 \implies 2x - 2 \ge 6 \implies x \ge 4\)។ បើ \(-1 < x < 3 \implies 4 \ge 6\) មិនពិត។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'hard', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10928, 'កសិករម្នាក់មានរបងប្រវែង 80 ម៉ែត្រសម្រាប់ព័ទ្ធសួនបន្លែរាងចតុកោណកែង។ តើផ្ទៃក្រឡាអតិបរិមាដែលគាត់អាចព័ទ្ធបានស្មើនឹងប៉ុន្មាន?', NULL, '["\\(300\\text{ m}^2\\)", "\\(400\\text{ m}^2\\)", "\\(800\\text{ m}^2\\)", "\\(360\\text{ m}^2\\)"]', 1, NULL, 3, 'mcq', 'កន្លះបរិមាត្រ \(x + y = 40\)។ តាម AM-GM ៖ \(\sqrt{xy} \le \dfrac{x+y}{2} = 20 \implies xy \le 400\)។ អតិបរមាគឺ 400 ម៉ែត្រការ៉េ (ពេលការេ x = y = 20)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'hard', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10929, 'ដោះស្រាយវិសមីការ \(\dfrac{x^2 - 9}{x - 1} \ge 0\)៖', NULL, '["\\([-3, 1) \\cup [3, +\\infty)\\)", "\\((-3, 1) \\cup (3, +\\infty)\\)", "\\((-\\infty, -3] \\cup (1, 3]\\)", "\\([-3, 3]\\)"]', 0, NULL, 3, 'mcq', 'សូន្យនៃភាគយក \(x = \pm 3\) និងភាគបែង \(x = 1\)។ តាមតារាងសញ្ញាកន្សោមវិជ្ជមានចំពោះ \([-3, 1) \cup [3, +\infty)\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'hard', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10930, 'រកតម្លៃ \(m\) ដើម្បីឱ្យវិសមីការ \(mx^2 - 4x + m < 0\) ផ្ទៀងផ្ទាត់ចំពោះគ្រប់ \(x \in \mathbb{R}\)៖', NULL, '["\\(m < -2\\)", "\\(m \\le -2\\)", "\\(m > 2\\)", "\\(-2 < m < 2\\)"]', 0, NULL, 3, 'mcq', 'លក្ខខណ្ឌ ៖ \(m < 0 \text{ និង } \Delta'' = 4 - m^2 < 0 \iff m^2 > 4 \iff m > 2 \text{ ឬ } m < -2\)។ ប្រសព្វនាំឱ្យ \(m < -2\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'hard', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10931, 'ចំពោះ \(x > 0\) តើតម្លៃអប្បបរមានៃកន្សោម \(C = x^2 + \dfrac{16}{x}\) (សរសេរ \(x^2 + \dfrac{8}{x} + \dfrac{8}{x}\)) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(16\\)", "\\(10\\)", "\\(8\\)", "\\(12\\)"]', 3, NULL, 3, 'mcq', 'តាម AM-GM 3 តួ ៖ \(x^2 + \dfrac{8}{x} + \dfrac{8}{x} \ge 3\sqrt[3]{x^2 \cdot \dfrac{8}{x} \cdot \dfrac{8}{x}} = 3\sqrt[3]{64} = 3(4) = 12\)។ សមភាពកើតពេល \(x^2 = 8/x \implies x = 2\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'hard', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10932, 'បុប្ផាធ្វើតេស្ត 3 មុខបានពិន្ទុ 89, 92, 82។ តើនាងត្រូវការពិន្ទុមុខទី 4 យ៉ាងតិចប៉ុន្មាន ដើម្បីឱ្យមធ្យមពិន្ទុទាំង 4 មុខយ៉ាងតិច 90?', NULL, '["\\(97 \\text{ ពិន្ទុ}\\)", "\\(99 \\text{ ពិន្ទុ}\\)", "\\(95 \\text{ ពិន្ទុ}\\)", "\\(90 \\text{ ពិន្ទុ}\\)"]', 0, NULL, 3, 'mcq', '\(\dfrac{89 + 92 + 82 + x}{4} \ge 90 \implies 263 + x \ge 360 \implies x \ge 97\)។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'pisa', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10933, 'ជណ្តើរយន្តអគារមួយផ្ទុកទម្ងន់អតិបរមា 600 kg។ មនុស្សពេញវ័យ 4 នាក់មានទម្ងន់ជាមធ្យម 75 kg ក្នុងម្នាក់ កំពុងជិះជណ្តើរយន្តនោះជាមួយកេសទំនិញមួយចំនួនដែលមានទម្ងន់ 25 kg ក្នុងមួយកេស។ តើអាចផ្ទុកកេសទំនិញបានច្រើនបំផុតប៉ុន្មានកេស?', NULL, '["\\(11 \text{ កេស}\\)", "\\(10 \text{ កេស}\\)", "\\(12 \text{ កេស}\\)", "\\(15 \text{ កេស}\\)"]', 2, NULL, 3, 'mcq', '\(4(75) + 25n \le 600 \implies 300 + 25n \le 600 \implies 25n \le 300 \implies n \le 12\) កេស។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'pisa', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10934, 'ក្រុមហ៊ុនទូរស័ព្ទមានគម្រោងអ៊ីនធឺណិតគិតថ្លៃថេរ $5 ក្នុងមួយខែ និងបន្ថែម $0.02 ក្នុង 1 MB ប្រើប្រាស់។ បើពិសីមានថវិកាអតិបរមាត្រឹមតែ $25 ក្នុងមួយខែ តើនាងអាចប្រើប្រាស់ទិន្នន័យបានច្រើនបំផុតប៉ុន្មាន MB?', NULL, '["\\(1\\,000\text{ MB}\\)", "\\(1\\,500\text{ MB}\\)", "\\(800\text{ MB}\\)", "\\(1\\,200\text{ MB}\\)"]', 0, NULL, 3, 'mcq', '\(5 + 0.02x \le 25 \implies 0.02x \le 20 \implies x \le \dfrac{20}{0.02} = 1\,000\) MB។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'pisa', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10935, 'សេវាតាក់ស៊ីមួយគិតថ្លៃដំបូង $1.50 សម្រាប់ 1 គីឡូម៉ែត្រដំបូង និងគិត $0.60 សម្រាប់គីឡូម៉ែត្របន្ថែមនីមួយៗ។ បើចាន់មានប្រាក់ $15 តើគាត់អាចជិះតាក់ស៊ីបានចម្ងាយអតិបរមាប៉ុន្មានគីឡូម៉ែត្រ?', NULL, '["\\(25\\text{ km}\\)", "\\(22.5\\text{ km}\\)", "\\(23.5\\text{ km}\\)", "\\(20\\text{ km}\\)"]', 2, NULL, 3, 'mcq', '\(1.50 + 0.60(d - 1) \le 15 \implies 0.60(d - 1) \le 13.50 \implies d - 1 \le 22.5 \implies d \le 23.5\) km។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'pisa', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10936, 'សិប្បកម្មផលិតវត្ថុអនុស្សាវរីយ៍មួយចំណាយថេរ $400 ក្នុងមួយខែ និងថ្លៃដើមផលិត $3 ក្នុងមួយឯកតា។ បើគេលក់ចេញក្នុងតម្លៃ $8 ក្នុងមួយឯកតា តើត្រូវផលិតនិងលក់យ៉ាងតិចប៉ុន្មានឯកតាដើម្បីទទួលបានប្រាក់ចំណេញយ៉ាងតិច $600 ក្នុងមួយខែ?', NULL, '["\\(150 \text{ ឯកតា}\\)", "\\(250 \text{ ឯកតា}\\)", "\\(200 \text{ ឯកតា}\\)", "\\(180 \text{ ឯកតា}\\)"]', 2, NULL, 3, 'mcq', '\(8x - (3x + 400) \ge 600 \implies 5x - 400 \ge 600 \implies 5x \ge 1\,000 \implies x \ge 200\) ឯកតា។', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'pisa', 1, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10937, 'ដោះស្រាយវិសមីការដឺក្រេទី 1 មានមួយអញ្ញាត ៖
\(3(x - 2) + 4 < 5x - 8\)', NULL, '[]', 0, NULL, 5, 'writing', 'ពន្លាតវង់ក្រចក ៖ \(3x - 6 + 4 < 5x - 8 \iff 3x - 2 < 5x - 8\) (1 ពិន្ទុ)
ផ្ទេរតួមានអថេរទៅអង្គទីមួយ និងចំនួនទៅអង្គទីពីរ ៖ \(3x - 5x < -8 + 2\) (1 ពិន្ទុ)
សម្រួល ៖ \(-2x < -6\) (1 ពិន្ទុ)
ចែកអង្គទាំងពីរនឹង -2 និងប្តូរទិសដៅវិសមភាព ៖ \(x > 3\) (1 ពិន្ទុ)
សន្និដ្ឋានសំណុំចម្លើយ \(S = (3, +\infty) 	ext{ ឬ } x > 3\) (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'easy', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10938, 'ដោះស្រាយប្រព័ន្ធវិសមីការដឺក្រេទី 1 មានមួយអញ្ញាត ៖
\(\begin{cases} 4x - 5 < 2x + 7 \\ 3(x + 1) \ge x - 1 \end{cases}\)', NULL, '[]', 0, NULL, 5, 'writing', 'ដោះស្រាយវិសមីការទីមួយ ៖ \(4x - 2x < 7 + 5 \implies 2x < 12 \implies x < 6\) (1 ពិន្ទុ)
ដោះស្រាយវិសមីការទីពីរ ៖ \(3x + 3 \ge x - 1 \implies 2x \ge -4 \implies x \ge -2\) (1 ពិន្ទុ)
គូសបញ្ជាក់ចន្លោះចម្លើយទាំងពីរលើបន្ទាត់ចំនួនតែមួយ (1 ពិន្ទុ)
រកប្រសព្វនៃសំណុំចម្លើយទាំងពីរ ៖ \(-2 \le x < 6\) (1 ពិន្ទុ)
សន្និដ្ឋានសំណុំចម្លើយ \(S = [-2, 6)\) (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10939, 'ដោះស្រាយវិសមីការដឺក្រេទី 2 ៖
\(x^2 - 4x - 5 \le 0\)', NULL, '[]', 0, NULL, 5, 'writing', 'ស្វែងរកឫសនៃសមីការ \(x^2 - 4x - 5 = 0\) ៖ \((x - 5)(x + 1) = 0 \implies x_1 = -1, \; x_2 = 5\) (1 ពិន្ទុ)
កំណត់មេគុណ \(a = 1 > 0\) (1 ពិន្ទុ)
សង់តារាងសញ្ញាត្រីធាដឺក្រេទី 2 ដោយបង្ហាញសញ្ញាក្នុងនិងក្រៅចន្លោះឫស (1 ពិន្ទុ)
ជ្រើសរើសចន្លោះដែលកន្សោមអវិជ្ជមានឬសូន្យ (សញ្ញាផ្ទុយ a) ៖ \(-1 \le x \le 5\) (1 ពិន្ទុ)
សន្និដ្ឋានសំណុំចម្លើយ \(S = [-1, 5]\) (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10940, 'ដោះស្រាយវិសមីការមានតម្លៃដាច់ខាត ៖
\(|3x - 2| \le 7\)', NULL, '[]', 0, NULL, 5, 'writing', 'ថ្លែងលក្ខណៈតម្លៃដាច់ខាត \(|u| \le a \iff -a \le u \le a \quad (a > 0)\) (1 ពិន្ទុ)
បំប្លែងវិសមីការជាវិសមីការពីរជាន់ ៖ \(-7 \le 3x - 2 \le 7\) (1 ពិន្ទុ)
បូក 2 លើគ្រប់អង្គ ៖ \(-5 \le 3x \le 9\) (1 ពិន្ទុ)
ចែកនឹង 3 លើគ្រប់អង្គ ៖ \(-\dfrac{5}{3} \le x \le 3\) (1 ពិន្ទុ)
សន្និដ្ឋានសំណុំចម្លើយ \(S = \left[-\dfrac{5}{3}, \; 3\right]\) (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10941, 'បង្ហាញថាចំពោះគ្រប់ចំនួនពិតវិជ្ជមាន \(x > 0\) គេតែងតែបាន \(x + \dfrac{1}{x} \ge 2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ថ្លែងវិសមភាព AM-GM ចំពោះពីរចំនួនវិជ្ជមាន a, b ៖ \(\dfrac{a + b}{2} \ge \sqrt{ab}\) (1 ពិន្ទុ)
អនុវត្តចំពោះ \(a = x\) និង \(b = \dfrac{1}{x} > 0\) ៖ \(\dfrac{x + \frac{1}{x}}{2} \ge \sqrt{x \cdot \dfrac{1}{x}}\) (1 ពិន្ទុ)
គណនាផលគុណ \(\sqrt{x \cdot \dfrac{1}{x}} = \sqrt{1} = 1\) (1 ពិន្ទុ)
គុណអង្គទាំងពីរនឹង 2 ៖ \(x + \dfrac{1}{x} \ge 2\) (1 ពិន្ទុ)
បញ្ជាក់លក្ខខណ្ឌសមភាពកើតមានកាលណា \(x = \frac{1}{x} \iff x^2 = 1 \implies x = 1\) (ព្រោះ x > 0) (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'medium', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10942, 'ដោះស្រាយវិសមីការសនិទាន ៖
\(\dfrac{2x - 3}{x + 2} \le 1\)', NULL, '[]', 0, NULL, 5, 'writing', 'ផ្ទេរអង្គខាងស្តាំទៅឆ្វេង ៖ \(\dfrac{2x - 3}{x + 2} - 1 \le 0\) (1 ពិន្ទុ)
តម្រូវភាគបែងរួម ៖ \(\dfrac{2x - 3 - (x + 2)}{x + 2} \le 0 \iff \dfrac{x - 5}{x + 2} \le 0\) (1 ពិន្ទុ)
កំណត់លក្ខខណ្ឌភាគបែង \(x + 2 \neq 0 \implies x \neq -2\) និងសូន្យភាគយក \(x = 5\) (1 ពិន្ទុ)
សង់តារាងសញ្ញាផលចែកដើម្បីរកចន្លោះអវិជ្ជមាន (1 ពិន្ទុ)
សន្និដ្ឋានសំណុំចម្លើយ \(S = (-2, 5] 	ext{ ឬ } -2 < x \le 5\) (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'hard', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10943, 'រកតម្លៃ \(m\) ដើម្បីឱ្យត្រីធា \(f(x) = x^2 - 2(m - 1)x + (2m + 1)\) វិជ្ជមានជានិច្ចចំពោះគ្រប់ \(x \in \mathbb{R}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បញ្ជាក់លក្ខខណ្ឌដើម្បីឱ្យ \(f(x) > 0\) គ្រប់ x ៖ \(a > 0 	ext{ និង } \Delta'' < 0\) (1 ពិន្ទុ)
កត់សម្គាល់មេគុណ \(a = 1 > 0\) ពិតជានិច្ច (1 ពិន្ទុ)
គណនា \(\Delta'' = (m - 1)^2 - (2m + 1) = m^2 - 2m + 1 - 2m - 1 = m^2 - 4m\) (1 ពិន្ទុ)
ដោះស្រាយវិសមីការ \(\Delta'' < 0 \iff m(m - 4) < 0\) (1 ពិន្ទុ)
សន្និដ្ឋានតម្លៃ m ដែលត្រូវរកគឺ \(0 < m < 4\) (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'hard', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10944, 'ដោះស្រាយវិសមីការ ៖
\(|2x - 1| < |x + 4|\)', NULL, '[]', 0, NULL, 5, 'writing', 'បញ្ជាក់ថាអង្គទាំងពីរវិជ្ជមាន អាចលើកជាការេបាន ៖ \((2x - 1)^2 < (x + 4)^2\) (1 ពិន្ទុ)
ផ្ទេរទៅអង្គតែមួយប្រើរូបមន្ត \(A^2 - B^2 = (A - B)(A + B) < 0\) (1 ពិន្ទុ)
គណនាកត្តា ៖ \(((2x - 1) - (x + 4))((2x - 1) + (x + 4)) = (x - 5)(3x + 3) < 0\) (1 ពិន្ទុ)
សម្រួល \(3(x - 5)(x + 1) < 0 \iff (x - 5)(x + 1) < 0\) (1 ពិន្ទុ)
សន្និដ្ឋានសំណុំចម្លើយ \(S = (-1, 5) 	ext{ ឬ } -1 < x < 5\) (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'hard', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10945, 'ចំពោះចំនួនពិតវិជ្ជមាន \(a, b, c > 0\) បង្ហាញថា ៖
\((a + b)(b + c)(c + a) \ge 8abc\)', NULL, '[]', 0, NULL, 5, 'writing', 'អនុវត្តវិសមភាព AM-GM លើកត្តានីមួយៗ ៖ \(a + b \ge 2\sqrt{ab}\) (1 ពិន្ទុ)
អនុវត្ត \(b + c \ge 2\sqrt{bc}\) (1 ពិន្ទុ)
អនុវត្ត \(c + a \ge 2\sqrt{ca}\) (1 ពិន្ទុ)
គុណអង្គនិងអង្គនៃវិសមភាពទាំងបី (ព្រោះតួនីមួយៗវិជ្ជមាន) ៖ \((a + b)(b + c)(c + a) \ge 2\sqrt{ab} \cdot 2\sqrt{bc} \cdot 2\sqrt{ca}\) (1 ពិន្ទុ)
សម្រួលផលគុណ \(8\sqrt{a^2b^2c^2} = 8abc\) រួចបញ្ជាក់ថាសមភាពកើតមានពេល \(a = b = c\) (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'hard', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10946, 'ការប្រឡងអាហារូបករណ៍មួយមាន 3 មុខវិជ្ជា៖ គណិតវិទ្យា (មេគុណ 3), រូបវិទ្យា (មេគុណ 2) និងភាសាអង់គ្លេស (មេគុណ 1)។ បេក្ខជនម្នាក់ទទួលបានពិន្ទុរូបវិទ្យា 78 និងអង់គ្លេស 85 (លើពិន្ទុពេញ 100)។
ក. សរសេរកន្សោមមធ្យមភាគពិន្ទុ \(\overline{X}\) ជាអនុគមន៍នៃពិន្ទុគណិតវិទ្យា \(m\)។
ខ. តើសិស្សនោះត្រូវទទួលបានពិន្ទុគណិតវិទ្យាយ៉ាងតិចប៉ុន្មាន ដើម្បីឱ្យមធ្យមភាគពិន្ទុសរុបយ៉ាងតិច 85?', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរកន្សោមមធ្យមភាគមានមេគុណ ៖ \(\overline{X} = \dfrac{3m + 2(78) + 1(85)}{3 + 2 + 1} = \dfrac{3m + 156 + 85}{6} = \dfrac{3m + 241}{6}\) (1 ពិន្ទុ)
បង្កើតវិសមីការ ៖ \(\dfrac{3m + 241}{6} \ge 85\) (1 ពិន្ទុ)
គុណអង្គទាំងពីរនឹង 6 ៖ \(3m + 241 \ge 510\) (1 ពិន្ទុ)
ដោះស្រាយរក m ៖ \(3m \ge 269 \implies m \ge \dfrac{269}{3} \approx 89.67\) (1 ពិន្ទុ)
សន្និដ្ឋានថាពិន្ទុគណិតវិទ្យាត្រូវតែយ៉ាងតិច 90 ពិន្ទុ (បើពិន្ទុជាចំនួនគត់) ឬ 89.67 (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'pisa', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10947, 'កសិករម្នាក់ចង់ធ្វើរបងព័ទ្ធដីរាងចតុកោណកែងមួយជាប់មាត់ស្ទឹង (មិនបាច់ធ្វើរបងខាងមាត់ស្ទឹងទេ) ដោយប្រើលួសប្រវែងសរុប 120 ម៉ែត្រ។
ក. តាង x ជាប្រវែងទទឹងនៃដីចម្ការ សរសេរផ្ទៃក្រឡា \(S(x)\) នៃចម្ការជាអនុគមន៍នៃ x។
ខ. រកវិមាត្រ x ដើម្បីឱ្យផ្ទៃក្រឡាចម្ការធំបំផុត និងគណនាផ្ទៃក្រឡាអតិបរមានោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង x ជាទទឹងទាំងសងខាង នោះបណ្តោយគឺ \(L = 120 - 2x\) (1 ពិន្ទុ)
សរសេរកន្សោមផ្ទៃក្រឡា ៖ \(S(x) = x(120 - 2x) = 120x - 2x^2 = -2(x^2 - 60x)\) (1 ពិន្ទុ)
បំពេញជាការេពេញលេញ ៖ \(S(x) = -2(x - 30)^2 + 1\,800\) (1 ពិន្ទុ)
ទាញរកតម្លៃអតិបរមា ៖ ដោយ \(-2(x - 30)^2 \le 0\) នោះ \(S(x) \le 1\,800	ext{ m}^2\) កើតមានពេល \(x = 30	ext{ m}\) (1 ពិន្ទុ)
សន្និដ្ឋានទទឹង \(x = 30	ext{ m}\) បណ្តោយ \(L = 60	ext{ m}\) និងផ្ទៃអតិបរមា \(1\,800	ext{ m}^2\) (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'pisa', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10948, 'ក្រុមហ៊ុនដឹកជញ្ជូនមួយគិតថ្លៃដឹកទំនិញដូចតទៅ៖
- ទម្ងន់ 5 kg ដំបូងគិតថ្លៃថេរ $12
- រាល់គីឡូក្រាមបន្ថែមបន្ទាប់ពី 5 kg គិត $1.80 ក្នុង 1 kg
អ្នកផ្ញើម្នាក់មានថវិកាត្រឹមតែ $48 សម្រាប់ផ្ញើទំនិញមួយកញ្ចប់។
ក. បង្កើតវិសមីការតាងទំនាក់ទំនងរវាងទម្ងន់ទំនិញ \(w\) (kg) និងថ្លៃចំណាយ។
ខ. រកទម្ងន់អតិបរមានៃកញ្ចប់ទំនិញដែលគាត់អាចផ្ញើបាន។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់កន្សោមថ្លៃចំណាយចំពោះ \(w \ge 5\) ៖ \(C(w) = 12 + 1.8(w - 5)\) (1 ពិន្ទុ)
បង្កើតវិសមីការតាមថវិកា ៖ \(12 + 1.8(w - 5) \le 48\) (1 ពិន្ទុ)
ដោះស្រាយវិសមីការ ៖ \(1.8(w - 5) \le 36 \implies w - 5 \le 20\) (1 ពិន្ទុ)
ទាញរក \(w \le 25	ext{ kg}\) (1 ពិន្ទុ)
សន្និដ្ឋានទម្ងន់អតិបរមាដែលអាចផ្ញើបានគឺ 25 kg (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'pisa', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10949, 'អាងស្តុកទឹកមួយចំណុះ 1\,200 លីត្រ កំពុងត្រូវបានបង្ហូរទឹកចេញតាមបំពង់បង្ហូរក្នុងអត្រា 25 លីត្រក្នុងមួយនាទី។
ក. សរសេរបរិមាណទឹកដែលនៅសល់ក្នុងអាង \(V(t)\) (លីត្រ) ក្រោយពេលបង្ហូរបាន t នាទី។
ខ. រយៈពេលបង្ហូរ t ត្រូវស្ថិតក្នុងចន្លោះណា ដើម្បីឱ្យបរិមាណទឹកនៅសល់ក្នុងអាងចន្លោះពី 200 លីត្រ ដល់ 450 លីត្រ?', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរសមីការបរិមាណទឹកនៅសល់ ៖ \(V(t) = 1\,200 - 25t\) (1 ពិន្ទុ)
បង្កើតវិសមីការពីរជាន់ ៖ \(200 \le 1\,200 - 25t \le 450\) (1 ពិន្ទុ)
ដក 1200 លើគ្រប់អង្គ ៖ \(-1\,000 \le -25t \le -750\) (1 ពិន្ទុ)
ចែកនឹង -25 និងប្តូរទិសដៅ ៖ \(\dfrac{-750}{-25} \le t \le \dfrac{-1\,000}{-25} \iff 30 \le t \le 40\) (1 ពិន្ទុ)
