INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 10950, 'គេមានបន្ទះក្រដាសរឹងរាងការេមួយជ្រុងប្រវែង 20 cm។ គេកាត់ការេតូចៗជ្រុង x (cm) ចេញពីជ្រុងទាំងបួន រួចបត់ធ្វើជាប្រអប់គ្មានគម្របមួយ។
ក. បង្ហាញថាកម្ពស់ប្រអប់គឺ x និងបាតប្រអប់ជាការេជ្រុង \(20 - 2x\) (លក្ខខណ្ឌ \(0 < x < 10\))។
ខ. រកលក្ខខណ្ឌ x ដើម្បីឱ្យផ្ទៃបាតប្រអប់យ៉ាងតិច 144 cm²។', NULL, '[]', 0, NULL, 5, 'writing', 'ពន្យល់វិមាត្រប្រអប់ ៖ កម្ពស់ x, ជ្រុងបាត \(20 - 2x\) និងលក្ខខណ្ឌ \(0 < x < 10\) (1 ពិន្ទុ)
បង្កើតវិសមីការផ្ទៃបាត ៖ \((20 - 2x)^2 \ge 144\) (1 ពិន្ទុ)
ដោយ \(20 - 2x > 0\) គេបាន \(20 - 2x \ge 12\) (1 ពិន្ទុ)
ដោះស្រាយរក x ៖ \(-2x \ge -8 \implies x \le 4\) (1 ពិន្ទុ)
រួមបញ្ចូលជាមួយលក្ខខណ្ឌ \(0 < x < 10\) សន្និដ្ឋាន \(0 < x \le 4	ext{ cm}\) (1 ពិន្ទុ)', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'pisa', 0, '10', 'វិសមីការនិងប្រព័ន្ធវិសមីការ', 'ជំពូកទី 3 : សមីការនិងវិសមីការ', NULL, 0);
